<script>document.addEventListener('DOMContentLoaded',function(){const main=document.querySelector('.bk-market-main-img'),thumbs=document.querySelectorAll('.bk-market-thumb');if(main&&thumbs.length){thumbs[0].classList.add('is-active');thumbs.forEach(function(t){t.addEventListener('click',function(){const i=t.querySelector('img');if(!i)return;main.src=i.src;main.removeAttribute('srcset');main.removeAttribute('sizes');thumbs.forEach(x=>x.classList.remove('is-active'));t.classList.add('is-active')})})}const tabs=document.querySelectorAll('.bk-market-tabs-nav a'),contents=document.querySelectorAll('.bk-market-tab-content');if(tabs.length&&contents.length){tabs.forEach(function(t){t.addEventListener('click',function(e){const id=t.getAttribute('href'),target=id?document.querySelector(id):null;if(!target)return;e.preventDefault();tabs.forEach(x=>x.classList.remove('is-active'));contents.forEach(x=>x.style.display='none');t.classList.add('is-active');target.style.display='block';target.scrollIntoView({behavior:'smooth',block:'start'})})})}});</script><?php },99);
